<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreEmployeeRequest extends FormRequest { public function authorize(): bool{return true;} public function rules(): array{return ['employee_id'=>'nullable|string|max:50|unique:employees,employee_id','hikvision_employee_no'=>'nullable|string|max:50|unique:employees,hikvision_employee_no','nik'=>'required|string|max:50|unique:employees,nik','name'=>'required|string|max:255','email'=>'nullable|email|max:255|unique:employees,email','phone'=>'nullable|string|max:50','photo_path'=>'nullable|string|max:255','card_no'=>'nullable|string|max:50','department'=>'required|string|max:100','role'=>'nullable|string|max:100','role_jabatan'=>'nullable|string|max:100','building_id'=>'nullable|exists:buildings,id','division_id'=>'nullable|exists:divisions,id','position_id'=>'nullable|exists:positions,id','employment_type'=>'nullable|string|max:50','employment_status'=>'nullable|in:ACTIVE,INACTIVE','hire_date'=>'nullable|date','fingerprint_enrolled'=>'nullable|boolean','card_enrolled'=>'nullable|boolean','door_ids'=>'nullable|array','door_ids.*'=>'exists:doors,door_id'];} }
